{
  "narrative_summary": "This result rests on the link from Customer Acquisition Cost to New Revenue. If that cost moves enough, more runs could support a different option. In this model, 41% of runs supported Self Serve Funnel.",
  "story_headlines": {
    "opt_selfserve": "Self Serve Funnel holds up because its modelled outcome stays strong even as acquisition cost varies.",
    "opt_paid": "Paid Acquisition would need acquisition cost to fall well below its current level to gain more support.",
    "opt_partner": "Partner Channel would need a materially stronger modelled outcome range to gain more support.",
    "opt_outbound": "Outbound Sales would need a narrower downside outcome range to gain more support."
  },
  "robustness_explanation": {
    "summary": "The ordering holds in about 64% of variations, a medium level of confidence overall.",
    "primary_risk": "The link from Customer Acquisition Cost to New Revenue is the single biggest threat to this result.",
    "stability_factors": [
      "Self Serve Funnel keeps a wide favourable outcome range across the modelled variations."
    ],
    "fragility_factors": [
      "The link from Customer Acquisition Cost to New Revenue could flip which option more runs support."
    ]
  },
  "readiness_rationale": "The comparison is settled enough to act on, though Customer Acquisition Cost is the one gap worth closing before committing fully.",
  "evidence_enhancements": {
    "fac_cac": {
      "specific_action": "Pull actual blended acquisition cost from the last two quarters of billing and marketing spend data.",
      "rationale": "This cost has the highest value of any gap for firming up this comparison.",
      "evidence_type": "internal_data",
      "decision_hygiene": "Estimate the current acquisition cost yourself before looking at the actual figure."
    }
  },
  "scenario_contexts": {
    "edge_cac_growth": {
      "trigger_description": "If Customer Acquisition Cost rises well beyond its current level...",
      "consequence": "...then the most runs would support Paid Acquisition rather than Self Serve Funnel."
    }
  },
  "flip_thresholds": [
    {
      "factor_id": "fac_cac",
      "factor_label": "Customer Acquisition Cost",
      "current_display": "420 GBP",
      "flip_display": "610 GBP",
      "narrative": "If Customer Acquisition Cost moves from 420 GBP to 610 GBP, more runs would support a different option."
    }
  ],
  "bias_findings": [],
  "key_assumptions": [
    "The link from Customer Acquisition Cost to New Revenue assumes current market conditions hold next quarter.",
    "The modelled outcome ranges assume no major change in how each channel converts spend into revenue."
  ],
  "decision_quality_prompts": [
    {
      "question": "What would make you switch to Paid Acquisition instead of Self Serve Funnel?",
      "principle": "Consider-the-opposite",
      "applies_because": "Self Serve Funnel's own share is well above the others, so it is worth actively testing what would overturn it."
    },
    {
      "question": "Choosing Self Serve Funnel, what does giving up Partner Channel and Outbound Sales cost?",
      "principle": "Opportunity Cost",
      "applies_because": "Four options are being weighed, so the cost of forgoing each alternative is worth naming explicitly."
    }
  ],
  "pre_mortem": {
    "failure_scenario": "Self Serve Funnel failed because Customer Acquisition Cost rose well beyond its modelled level, eroding the favourable outcome range that supported it.",
    "warning_signs": [
      "Acquisition cost trending upward across consecutive weeks.",
      "New Revenue growth slowing while spend holds steady."
    ],
    "mitigation": "Set a review point tied to acquisition cost before committing the full budget.",
    "grounded_in": ["edge_cac_growth", "fac_cac"],
    "review_trigger": "Reconvene if acquisition cost climbs materially before next planning cycle."
  }
}
